// 393C:0005
// Borland _read layer. Binary handles return the raw DOS result; text handles
// discard CR bytes, preserve LF, and treat Ctrl-Z as logical end-of-file.
int16 ReadFileWithTextTranslation(
	word16 fileHandle,
	byte *buffer,
	word16 requestedBytes)
{
	word16 fileState;

	if (requestedBytes == 0x00)
		return 0x00;

	fileState = FileRuntime.handleState[fileHandle];
	if ((fileState & CRT_FILE_STATE_TEXT_EOF) != 0x00)
		return 0x00;

	for (;;)
	{
		int16 rawBytesRead = DOS_ReadFile(fileHandle, buffer, requestedBytes);
		byte *source;
		byte *destination;
		word16 remaining;

		if (rawBytesRead < 0x01 ||
			(fileState & CRT_FILE_STATE_BINARY) != 0x00)
			return rawBytesRead;

		source = buffer;
		destination = buffer;
		remaining = rawBytesRead;
		while (remaining != 0x00)
		{
			byte value = *source++;

			if (value == 0x1A)
			{
				DOS_SeekFile(
					fileHandle,
					-(long) remaining,
					DOS_SEEK_FROM_CURRENT);
				FileRuntime.handleState[fileHandle] |= CRT_FILE_STATE_TEXT_EOF;
				return (int16) (destination - buffer);
			}

			--remaining;
			if (value != 0x0D)
				*destination++ = value;
		}

		// A CR at the very end of a DOS read is discarded and one following byte
		// is fetched so a split CR/LF pair still yields its LF in this result.
		if (rawBytesRead != 0x00 && source[-0x01] == 0x0D)
		{
			byte followingByte;
			DOS_ReadFile(fileHandle, &followingByte, 0x01);
			*destination++ = followingByte;
		}

		if (destination != buffer)
			return (int16) (destination - buffer);
	}
}
